def solve_our(case,preds,th):
    S=len(case['slots']);J=len(case['windows']);F=len(case['flows'])
    vals=case['class_values'];wins=case['windows']
    Rvals=sorted(set(Fraction(k,t) for target,t,gg,ll in case['flows'] for k in range(0,t+1)))
    def feas(r):
        return circulation_feasible(case,preds,th,r,False,False)[0]
    left=0;right=len(Rvals)
    while right-left>1:
        mid=(left+right)//2
        if feas(Rvals[mid]):left=mid
        else:right=mid
    r=Rvals[left]
    if r==0:
        K,R,Z,a,b,e,w,z,h,arcs=build_arcs(case,preds,th,r)
        f=[l for u,v,l,h,c in arcs]
    else:
        ok,cut,f=circulation_feasible(case,preds,th,r,False,True)
        if not ok:raise RuntimeError('best infeasible')
    f=fill_circulation(case,preds,th,r,f)
    K,R,Z,a,b,e,w,z,h,arcs=build_arcs(case,preds,th,r)
    sp=special_for(case,preds,th,arcs)
    ns=NetworkSimplex(K,arcs,f)
    ns.solve(special=sp)
    # extract assign etc
    assign=[-1]*J;sel=[];U=A=0
    eset=set(e);wset=set(w);W=1+J*case['slots'][-1][0]
    for i,(u,v,l,h,c) in enumerate(arcs):
        if ns.flow[i]>0 and u in eset and v in wset:
            j=v-(2+3*S);s=(u-4)//3
            if assign[j]!=-1:raise RuntimeError('double assign')
            assign[j]=s;sel.append(j);U+=wins[j][6]*vals[preds[j]];A+=case['slots'][s][0]-wins[j][1]
    # verify flows lower/cap/conservation
    for i,(u,v,l,h,c) in enumerate(arcs):
        if not (l<=ns.flow[i]<=h):raise RuntimeError('bound')
    bal=[0]*K
    for i,(u,v,l,h,c) in enumerate(arcs):bal[u]+=ns.flow[i];bal[v]-=ns.flow[i]
    if any(bal):raise RuntimeError(('bal',bal))
    return r,U,A,assign,ns

def brute(case,th):
    S=len(case['slots']);J=len(case['windows']);F=len(case['flows']);G=len(case['groups'])
    slots=case['slots'];wins=case['windows'];flows=case['flows'];groups=case['groups']
    vals=case['class_values'];B,I=case['bucket']
    # ancestor group list per flow and group info
    anc=[]
    for f,(t,c,g,l) in enumerate(flows):
        if g==-1:anc.append([])
        else:
            path=[];x=g
            while x!=-1:
                path.append(x);x=groups[x][0]
            anc.append(path)
    # enumerate assignment per window
    opts=[]
    for j,w in enumerate(wins):
        if w[5]>=th[j]:opts.append([-1])
        else:
            # note th passed; gate independent
            opts.append([-1]+[s for s,(tm,cp,rf) in enumerate(slots) if w[1]<=tm<=w[2]])
    best=None;bestdata=None
    for ass in itertools.product(*opts):
        # token feasibility
        cnt=[0]*S
        for s in ass:
            if s>=0:cnt[s]+=1
        avail=I;ok=True
        for s,(tm,cp,rf) in enumerate(slots):
            if s>0:avail=min(B,avail+rf)
            if cnt[s]>cp or cnt[s]>avail:ok=False;break
            avail-=cnt[s]
        if not ok:continue
        nf=[0]*F
        for j,s in enumerate(ass):
            if s>=0:nf[wins[j][0]]+=1
        if any(nf[f]>flows[f][1] for f in range(F)):continue
        gc=[0]*G
        for f in range(F):
            for g in anc[f]:gc[g]+=nf[f]
        if any(gc[g]>groups[g][1] for g in range(G)):continue
        cov=min([Fraction(min(1,nf[f]/flows[f][0])) for f in range(F)] or [Fraction(0)])
        U=sum((wins[j][6]*vals[0]) for j,s in enumerate(ass) if s>=0) # placeholder
        U=sum(wins[j][6]*case.get('_predvals',[0]*J)[j] for j,s in enumerate(ass) if s>=0)
        A=sum(slots[s][0]-wins[j][1] for j,s in enumerate(ass) if s>=0)
        key=(cov,U,-A)
        if best is None or key>best:
            best=key;bestdata=ass
    return best,bestdata

